{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `maplemonk.ka_s3_distribution_sales_data` AS WITH extracted AS ( SELECT SAFE_CAST(REGEXP_EXTRACT(_airbyte_Data, r\'\"Actual Qty\"\s*:\s*\"([^\"]*)\"\') AS INT64) AS actual_qty, SAFE_CAST(REGEXP_EXTRACT(_airbyte_Data, r\'\"Qty\"\s*:\s*\"([^\"]*)\"\') AS INT64) AS qty, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Category\"\s*:\s*\"([^\"]*)\"\')) AS category, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Voucher Type\"\s*:\s*\"([^\"]*)\"\')) AS voucher_type, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"RSM Name\"\s*:\s*\"([^\"]*)\"\')) AS rsm_name, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"ASM Name\"\s*:\s*\"([^\"]*)\"\')) AS asm_name, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"HQ/Location\"\s*:\s*\"([^\"]*)\"\')) AS hq_location, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Party Name\"\s*:\s*\"([^\"]*)\"\')) AS party_name, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Item Part No\"\s*:\s*\"([^\"]*)\"\')) AS item_part_no, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Company Name\"\s*:\s*\"([^\"]*)\"\')) AS company_name, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Item Name\"\s*:\s*\"([^\"]*)\"\')) AS item_name, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"BDE Name\"\s*:\s*\"([^\"]*)\"\')) AS bde_name, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Item_Batch\"\s*:\s*\"([^\"]*)\"\')) AS item_batch, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Item Group\"\s*:\s*\"([^\"]*)\"\')) AS item_group, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Item HSN\"\s*:\s*\"([^\"]*)\"\')) AS item_hsn, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"Discount\"\s*:\s*\"([^\"]*)\"\'), \'%\', \'\') AS NUMERIC) AS discount, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"MRP\"\s*:\s*\"([^\"]*)\"\'), \',\', \'\') AS NUMERIC) AS mrp, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"Item GST\"\s*:\s*\"([^\"]*)\"\'), \',\', \'\') AS NUMERIC) AS item_gst, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"Sales Value\(With Tax\)\"\s*:\s*\"([^\"]*)\"\'), \',\', \'\') AS NUMERIC) AS sales_value_with_tax, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"Amount\"\s*:\s*\"([^\"]*)\"\'), \',\', \'\') AS NUMERIC) AS amount, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"GST Amount\"\s*:\s*\"([^\"]*)\"\'), \',\', \'\') AS NUMERIC) AS gst_amount, SAFE_CAST(REPLACE(REGEXP_EXTRACT(_airbyte_Data, r\'\"Rate\(NRV\)\"\s*:\s*\"([^\"]*)\"\'), \',\', \'\') AS NUMERIC) AS rate_nrv, SAFE.PARSE_DATE( \'%d-%b-%y\', TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Date\"\s*:\s*\"([^\"]*)\"\')) ) AS txn_date, TRIM(REGEXP_EXTRACT(_airbyte_Data, r\'\"Voucher Number\"\s*:\s*\"([^\"]*)\"\')) AS voucher_number FROM `maplemonk._airbyte_raw_KA_S3_Distribution_Sales` ), ranked AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY voucher_number, item_batch, item_name ORDER BY voucher_number ) AS rn FROM extracted ) SELECT * EXCEPT(rn) FROM ranked WHERE rn = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
